from lib import *
S = SS('w26')
steps = [
    step("本机跟 SLAAC / 邻居发现有关的内核参数:accept_rtadv = 1(接受路由器通告)、auto_linklocal = 1(自动生成链路本地地址)、use_tempaddr = 1(启用隐私扩展的临时地址)、temppltime = 86400(临时地址首选寿命 24 小时)、tempvltime = 604800(有效寿命 7 天)、dad_count = 1(重复地址检测发 1 次)、nd6_optimistic_dad = 63、auto_flowlabel = 1(内核自动填流标签,第 23 篇里看到的)、nd6_delay = 5(DELAY 阶段 5 秒,上一篇实测的 5 秒)、nd6_mmaxtries = 3 和 nd6_umaxtries = 3。各接口的链路本地地址:有 MAC 的 3 个接口(en0、awdl0、llw0)里,awdl0 和 llw0 的接口标识符是 MAC 推出的 EUI-64,en0 不是(地址标志 secured);lo0 和 utun0~utun3 没有 MAC。", t=tl(S(1)), mark=lidx(S(1), 'use_tempaddr', 'en0    有 MAC', 'awdl0', 'llw0'), done=lidx(S(1), 'accept_rtadv', 'auto_linklocal', 'temppltime', 'dad_count', 'nd6_delay', '有 MAC 的接口'), kv=KV([['临时地址', '首选 24 小时 / 有效 7 天'], ['DAD', '发 1 次'], ['nd6_delay', '5 秒(DELAY 阶段)'], ['EUI-64 的接口', 'awdl0、llw0;en0 不是']], ['EUI-64 的接口'])),
    step("SLAAC 地址怎么拼(计算,不是抓来的):假设路由器通告了前缀 2001:db8:1:2::/64。三种接口标识符:1. EUI-64:示例 MAC 00:11:22:33:44:55 中间插 ff:fe 并翻转第 7 位得 0211:22ff:fe33:4455,由 MAC 决定,在任何网络里都一样。2. 稳定不透明(RFC 7217 风格,这里的哈希方案是简化的):哈希(前缀, 接口名, 本机秘密值, DAD 计数)的前 64 位 → 1c7b:e47c:206a:da37,同一前缀每次算出都相同;换前缀 2001:db8:9:9::/64 得 bf28:db64:a331:f008,不同。3. 临时地址(RFC 8981 风格):每个首选寿命周期随机生成一个,例如 2291:d8cd:c310:411e、7ec2:7378:a661:c935、187c:07e4:d563:6e9b。拼出来的地址:2001:db8:1:2:211:22ff:fe33:4455(EUI-64)、2001:db8:1:2:1c7b:e47c:206a:da37(稳定)、2001:db8:1:2:2291:d8cd:c310:411e(临时)。同一台机器走到两个网络里,EUI-64 的后 64 位相同(可被跟踪),稳定地址的后 64 位不同。", t=tl(S(2)), mark=lidx(S(2), '1. EUI-64', '2. 稳定不透明', '3. 临时地址'), done=lidx(S(2), '示例 MAC', '拼出来的地址', 'EUI-64 的缺点', '同一台机器在两个网络'), kv=KV([['EUI-64', '由 MAC 决定,换网络不变(可跟踪)'], ['稳定不透明', '同一前缀不变,换前缀就变'], ['临时', '随机,首选寿命到期换新的']], ['稳定不透明'])),
    step("被动听 120 秒 en0 上的 ND 流量:共 24 个 ICMPv6 报文,NS 12 个、NA 12 个;其中 NS 全是单播(NUD 探测)12 个,源地址为 ::(DAD 探测)的 0 个,发往被请求节点组播的 0 个。RA 路由器通告 0 个,RS 也没有。这条链路上没有路由器在发通告(与上一篇 ndp -rn 一致),所以本机即使开着 accept_rtadv,也没有 SLAAC 可做,只有链路本地地址。120 秒没抓到 RA 不能证明路由器不存在(通告间隔常是几分钟),但邻居缓存里没有路由器是另一个独立证据;别的设备的 DAD 这 120 秒里也没有出现。", t=tl(S(3)), mark=lidx(S(3), 'RA 路由器通告', '其中 NS 里'), done=lidx(S(3), '120 秒共抓到'), b=bars([['NS 邻居请求(单播探测)', 12, '12'], ['NA 邻居通告', 12, '12'], ['RA 路由器通告', 0, '0'], ['DAD 探测(源 ::)', 0, '0']], 12, mark=[2, 3], done=[0, 1]), kv=KV([['120 秒 ND 流量', 'NS 12 / NA 12'], ['RA / RS', '0 / 0'], ['DAD(源地址 ::)', '0 个'], ['结论', '链路上没有路由器通告']], ['结论'])),
    step("没有 IPv6 路由器时应用看到什么:example.com 在 DNS 里有 2 个 A 记录和 2 个 AAAA 记录,但本机 getaddrinfo(默认和加 AI_ADDRCONFIG 都一样)只返回 2 个 IPv4 地址,第一项是 IPv4——系统解析器在这台没有全球 IPv6 地址的机器上没有把 IPv6 地址交给应用(为什么,这里没有深究)。route get -inet6 到 example.com 的 IPv6 地址,回答是 not in table;直接 connect 该 IPv6 地址,0.1 ms 就报 No route to host,不用等超时。也就是说没有 IPv6 路由时,内核立刻失败;应用能否退回 IPv4,取决于它有没有这个逻辑(下一篇的 Happy Eyeballs)。", t=tl(S(4)), mark=lidx(S(4), 'connect 到该 IPv6 地址', 'route get -inet6'), done=lidx(S(4), '经 DNS 查', 'getaddrinfo(example.com, 80) 使用 默认', 'AI_ADDRCONFIG'), b=bars([['DNS 的 A 记录', 2, '2'], ['DNS 的 AAAA 记录', 2, '2'], ['getaddrinfo 返回的 IPv6 项', 0, '0']], 2, mark=[2], done=[0, 1]), kv=KV([['DNS', '2 个 A + 2 个 AAAA'], ['getaddrinfo', '只给 IPv4'], ['connect IPv6', '0.1 ms: No route to host']], ['getaddrinfo'])),
]
A = mkartw('w26', 26, '网络协议,SLAAC,IPv6,EUI-64,临时地址,隐私扩展,DAD,真实验证,动画演示',
    '本机 SLAAC 相关参数(临时地址首选 24 小时、有效 7 天、DAD 发 1 次);EUI-64 / 稳定不透明 / 临时三种接口标识符的计算与换网络后的差别;120 秒没有听到任何 RA;没有 IPv6 路由时 getaddrinfo 只返回 IPv4,connect IPv6 在 0.1 ms 失败。',
    'IPv6 主机怎么不靠 DHCP 就给自己配好地址?为什么 EUI-64 会暴露设备身份,临时地址又是什么?这篇先看本机的 SLAAC 参数和各接口地址的生成方式,再用计算演示三种接口标识符,最后看这个没有 IPv6 路由器的网络里应用看到的现象。',
    [('24 小时 / 7 天', '本机临时地址的首选寿命与有效寿命(temppltime / tempvltime)'), ('0 个 RA', '在 en0 上听 120 秒收到的路由器通告个数:这条链路上没有 IPv6 路由器,所以没有 SLAAC'), ('0.1 ms', '连接 example.com 的 IPv6 地址时内核报 No route to host 所用的时间')],
    [('SLAAC 的前提', '<p>路由器通告前缀(RA),主机用前缀加自己生成的 64 位接口标识符拼出地址,再做重复地址检测(DAD)。本机参数已打开 accept_rtadv,但这条链路上听不到 RA,所以只有链路本地地址。</p>'),
     ('接口标识符', '<p>EUI-64 由 MAC 决定,换网络不变,可被跟踪;稳定不透明在同一前缀内不变,换前缀就变;临时地址随机并定期更换。本机 en0 的链路本地地址就是稳定不透明的(secured),而 awdl0 和 llw0 仍是 EUI-64。</p>'),
     ('临时地址', '<p>本机 use_tempaddr = 1,临时地址首选 24 小时,到期换新的;有效 7 天后才彻底作废。</p>'),
     ('没有 IPv6 路由时', '<p>getaddrinfo 在这台机器上只返回 IPv4;若硬连 IPv6 地址,内核立刻报 No route to host。是否自动回退由应用决定。</p>')],
    steps,
    [ENV_W + '。本机网络没有 IPv6 路由器,所以没有观察到 RA / SLAAC 的实际过程;第二节是计算(稳定不透明地址的哈希是简化方案,不是 RFC 7217 的精确算法),示例 MAC 是虚构的;第三节只抓 120 秒,别的设备的流量只统计个数',
     '没有验证:真实的 RA 内容(前缀选项、M / O 标志、RDNSS 选项);DAD 的实际过程与 optimistic DAD;临时地址的实际生成和轮换(本机没有全球前缀);DHCPv6 和 SLAAC 的配合;getaddrinfo 为什么在没有 IPv6 地址时不返回 AAAA(系统解析器行为)'],
    'SLAAC 与隐私地址')
